#!/bin/bash
# Disposable GRUB rendering check. Builds a GRUB rescue ISO containing the Libertix theme
# (generated by the repository's generate-theme.sh) and a menu rendered by the repository's
# render-libertix-menu.py from Ubuntu 24.04-shaped generator output, then boots it in QEMU
# with no disks attached and captures the root menu, Advanced options, and the nested submenu.
#
# Usage: grub-vm.sh <label> <checkout-dir>   (checkout-dir holds grub/ and assets/grub-theme/)
set -euo pipefail
label=$1; checkout=$2
here=$(cd "$(dirname "$0")" && pwd)
prefix=/lbx-grub-1/root
work=/lbx-work/grub-vm/$label
out=$here/out/$label
mkdir -p "$work" "$out"
export PATH=/lbx-work/bin:$prefix/usr/bin:$PATH
export LD_LIBRARY_PATH=$prefix/usr/lib/x86_64-linux-gnu pkgdatadir=$prefix/usr/share/grub

# ImageMagick 7's "magick" front end, mapped onto the IM6 tools available here.
cat > /lbx-work/bin/magick <<'EOF'
#!/bin/sh
if [ "$1" = identify ]; then shift; exec identify "$@"; fi
exec convert "$@"
EOF
chmod 0755 /lbx-work/bin/magick

tree=$work/iso
find "$tree" -mindepth 1 -delete 2>/dev/null || true
mkdir -p "$tree/boot/grub"
bash "$checkout/assets/grub-theme/generate-theme.sh" 1024x768 "$tree/boot/grub/themes/Libertix" >/dev/null

fixtures=$work/fixtures
mkdir -p "$fixtures"
classes="--class linux --class gnu-linux --class gnu --class os"
cat > "$fixtures/linux.cfg" <<EOF
menuentry 'Linux Mint 22.3 Cinnamon' $classes \$menuentry_id_option 'gnulinux-simple-u1' {
	echo boot
}
submenu 'Advanced options for Linux Mint 22.3 Cinnamon' \$menuentry_id_option 'gnulinux-advanced-u1' {
	menuentry 'Linux Mint 22.3 Cinnamon, with Linux 6.8.0-90-generic' $classes \$menuentry_id_option 'gnulinux-6.8.0-90-generic-advanced-u1' {
		echo boot
	}
	menuentry 'Linux Mint 22.3 Cinnamon, with Linux 6.8.0-90-generic (recovery mode)' $classes \$menuentry_id_option 'gnulinux-6.8.0-90-generic-recovery-u1' {
		echo boot
	}
}
EOF
cat > "$fixtures/windows.cfg" <<'EOF'
menuentry "Windows Boot Manager" --class windows --class os --id libertix-windows {
	echo windows
}
EOF
# Without the platform guard, so both firmware runs show the entry.
cat > "$fixtures/firmware.cfg" <<'EOF'
menuentry 'UEFI Firmware Settings' $menuentry_id_option 'uefi-firmware' {
	fwsetup
}
EOF
cat > "$fixtures/memtest.cfg" <<'EOF'
menuentry "Memory test (memtest86+x64.efi)" --class memtest $menuentry_id_option 'memtest86+' {
	echo memtest
}
EOF
# An entry the renderer cannot classify: it should get the transparent fallback.
cat > "$fixtures/custom.cfg" <<'EOF'
menuentry "Custom tool (unrecognised)" $menuentry_id_option 'custom-tool' {
	echo custom
}
EOF
cat > "$fixtures/plan.json" <<'EOF'
{"distribution": {"grubDisplayName": "Linux Mint 22.3 Cinnamon", "grubIcon": "linuxmint"},
 "locale": {"languageCode": "en"}}
EOF

{
  cat <<'EOF'
set timeout=-1
set menuentry_id_option="--id"
insmod all_video
insmod gfxterm
insmod png
set gfxmode=1024x768
terminal_output gfxterm
for font in $prefix/themes/Libertix/*.pf2; do loadfont $font; done
set theme=$prefix/themes/Libertix/theme.txt
export theme
EOF
  python3 "$checkout/grub/render-libertix-menu.py" \
    --linux "$fixtures/linux.cfg" --windows "$fixtures/windows.cfg" \
    --firmware "$fixtures/firmware.cfg" --extra "$fixtures/memtest.cfg" \
    --extra "$fixtures/custom.cfg" --plan "$fixtures/plan.json"
} > "$tree/boot/grub/grub.cfg"
cp "$tree/boot/grub/grub.cfg" "$out/grub.cfg"
ls "$tree/boot/grub/themes/Libertix/icons" | grep -v '\.png$' > "$out/theme-non-png-files.txt" || true
grub-script-check "$tree/boot/grub/grub.cfg"

for firmware in bios uefi; do
  platform=i386-pc; [ $firmware = uefi ] && platform=x86_64-efi
  iso=$work/$firmware.iso
  grub-mkrescue -d "$prefix/usr/lib/grub/$platform" --fonts= --locales= --themes= \
    -o "$iso" "$tree" 2>&1 | grep -iv "^xorriso|^Drive|^Media|^ISO image|^Writing|^Added|^libburn|^libisofs|^GNU xorriso|^$" || true
  sock=$work/$firmware.sock
  rm -f "$sock"
  args=(-accel kvm -m 512 -vga std -display none -cdrom "$iso" -net none
        -monitor "unix:$sock,server,nowait")
  if [ $firmware = uefi ]; then
    cp "$prefix/usr/share/OVMF/OVMF_VARS_4M.fd" "$work/vars.fd"
    args+=(-drive "if=pflash,format=raw,readonly=on,file=$prefix/usr/share/OVMF/OVMF_CODE_4M.fd"
           -drive "if=pflash,format=raw,file=$work/vars.fd")
  fi
  qemu-system-x86_64 "${args[@]}" &
  qemu=$!
  python3 "$here/drive.py" "$sock" "$out/$firmware"
  wait $qemu || true
  for frame in "$out/$firmware"-*.ppm; do convert "$frame" "${frame%.ppm}.png" && rm "$frame"; done
done
ls "$out"
